pub fn block_write_ptr(ptr: *mut Node, Tracked(perm): Tracked<PointsToRaw>, next: *mut Node)
    -> (res: (Tracked<PointsTo<Node>>, Tracked<PointsToRaw>))
    requires
        perm.contains_range(ptr as int, size_of::<Node>() as int),
