            self.perms@.index((i - 1) as nat).0.ptr()
        }
    }

    pub closed spec fn valid_node(&self, i: nat, next_ptr: *mut Node) -> bool {
        0 <= i < self.data@.len ==> (
            self.perms@.dom().contains(i) && {
                  let (perm, padding, block_token, is_exposed) = self.perms@.index(i);

                  perm.is_init()
